namespace EasyServiceManager.Services

open System
open System.Text.RegularExpressions

/// <summary>多言語リソースの解決とフォーマットを行うモジュール。</summary>
module Localization =
    /// <summary>対応している言語コードと表示名の配列。</summary>
    let languages =
        [| "ja-JP", "日本語"
           "en-US", "English"
           "zh-CN", "简体中文"
           "zh-TW", "繁體中文"
           "ko-KR", "한국어"
           "vi-VN", "Tiếng Việt"
           "de-DE", "Deutsch"
           "fr-FR", "Français"
           "es-ES", "Español"
           "it-IT", "Italiano"
           "pt-BR", "Português (Brasil)"
           "ru-RU", "Русский" |]

    /// <summary>言語コードを既知の対応コードに正規化します（未対応の場合は ja-JP）。</summary>
    let normalizeCode (code: string) =
        languages
        |> Array.tryFind (fun (languageCode, _) -> languageCode = code)
        |> Option.map fst
        |> Option.defaultValue "ja-JP"

