    /// <summary>指定された言語コードに対応する配列インデックスを取得します。</summary>
    let private languageIndex code =
        languages
        |> Array.tryFindIndex (fun (languageCode, _) -> languageCode = normalizeCode code)
        |> Option.defaultValue 0

    /// <summary>指定された言語コードで静的テキストを翻訳します。</summary>
    let translate code (text: string) =
        match Map.tryFind text translations with
        | Some values -> values.[languageIndex code]
        | None -> if languageIndex code = 1 then text else text

    /// <summary>動的プレースホルダーを含むメッセージを指定言語へ翻訳します。</summary>
    let translateText code (text: string) =
        let dynamicPatterns =
            [ Regex("^ポート (.+) が全インターフェースで待ち受けています。外部から到達可能かはFirewallやNATにも依存します。$"),
              "ポート {0} が全インターフェースで待ち受けています。外部から到達可能かはFirewallやNATにも依存します。"
              Regex("^([0-9]+) 件のサービスを検出しました$"), "{0} 件のサービスを検出しました"
              Regex("^ブラウザを起動できませんでした: (.+)$"), "ブラウザを起動できませんでした: {0}"
              Regex("^設定を保存できませんでした: (.+)$"), "設定を保存できませんでした: {0}"
              Regex("^保存しました: (.+)$"), "保存しました: {0}"
              Regex("^保存に失敗しました: (.+)$"), "保存に失敗しました: {0}"
              Regex("^PermitRootLogin (.+) です。$"), "PermitRootLogin {0} です。"
              Regex("^PasswordAuthentication (.+) です。$"), "PasswordAuthentication {0} です。"
              Regex("^privilegedコンテナーがあります: (.+)$"), "privilegedコンテナーがあります: {0}"
              Regex("^全インターフェースに公開されたホストポート: (.+)。外部到達性はFirewallやNATにも依存します。$"),
              "全インターフェースに公開されたホストポート: {0}。外部到達性はFirewallやNATにも依存します。"
              Regex("^全インターフェースに公開されたコンテナーポート: (.+)。外部到達性はFirewallやNATにも依存します。$"),
              "全インターフェースに公開されたコンテナーポート: {0}。外部到達性はFirewallやNATにも依存します。"
              Regex("^前回から変化: 新規待ち受け \\((.+)\\)$"), "前回から変化: 新規待ち受け ({0})"
              Regex("^前回から変化: バインド変化 \\((.+)\\)$"), "前回から変化: バインド変化 ({0})"
              Regex("^新規サービス: (.+)$"), "新規サービス: {0}"
              Regex("^サービス起動: (.+)$"), "サービス起動: {0}"
              Regex("^新規待ち受け: (.+)$"), "新規待ち受け: {0}"
              Regex("^バインド変化: (.+)$"), "バインド変化: {0}"
              Regex("^待ち受けリスナー \\((.+)\\)$"), "待ち受けリスナー ({0})" ]
        match dynamicPatterns |> List.tryPick (fun (pattern, template) ->
            let matched = pattern.Match(text)
            if matched.Success then Some(template, matched.Groups.[1].Value) else None) with
        | Some(template, argument) ->
            let localizedTemplate = translate code template
            let safeArgument = argument
            try String.Format(localizedTemplate, safeArgument)
            with :? FormatException -> text
        | None -> translate code text

    /// <summary>翻訳済みテンプレート文字列を書式指定引数でフォーマットします。</summary>
    let format code template (arguments: obj array) =
        try String.Format(translate code template, arguments)
        with :? FormatException -> template
